// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 warpTime) public {
        amount = bound(amount, 10 ether, 100 ether);
        warpTime = bound(warpTime, 1, type(uint32).max);
        vm.assume(amount == 10 ether);
        vm.deal(address(this), amount);
        vm.warp(warpTime);
        vm.roll(1);
        (bool success,) = address(c).call{value: amount}("");
        assertTrue(success);
        assertTrue(c.pastBlockTime() >= warpTime);
    }
}
